    private static void AssertFeasibilityRejection(string label,string expectedRejection)
    {
        var session=new SessionAuthorityStampV1(RuntimeGenerationId.FromValue(Id(50)),LiveSessionId.FromValue(Id(51)));
        var graph=GraphGenerationId.FromValue(Id(52));var operation=OperationId.FromValue(Id(53));
        var authority=ExpectedAuthorityVectorV1.Create(session,[new AuthorityAxisValueV1.Graph(graph)]);
        var stamp=new MonotonicStampV1(ClockDomainId.FromValue(Id(54)),BootId.FromValue(Id(55)),1);
        var body=new GraphParticipantReservationCommandBodyV2(operation,null,session.RuntimeGenerationId,graph,Hash256.Compute([1]),Hash256.Compute([2]),new("fac"+"tory"),[new("a"),new("b")],stamp);
        var validCommandBodyBytes=GraphParticipantReservationCodecsV2.Encode(body);
        var validCommandBytes=GraphParticipantReservationCodecsV2.Encode(new GraphParticipantReservationCommandV2(session,authority,validCommandBodyBytes));

        var descriptor=new LiveAudioParticipantDescriptorV1(new("fac"+"tory"),OwnerSliceId.S2,AuthorityAxisId.Graph,[],[new CapacityDimensionId(1)],new(1),new(1),new(1));
        var validCarrierBytes=LiveAudioParticipantCatalogManifestV1.EncodeGraphParticipantAllocationDeclaration("fac"+"tory",["a","b"],[1],[new string('1',32)],[1],[1]);
        using var carrierHasher=IncrementalHash.CreateHash(HashAlgorithmName.SHA256);carrierHasher.AppendData("hpd-graph-participant-allocation-declaration-v1\0"u8);carrierHasher.AppendData(validCarrierBytes);var validCarrierFingerprint=Hash256.FromBytes(carrierHasher.GetHashAndReset());
        switch(label){case "expected-authority-session":Assert.False(GraphParticipantReservationCodecsV2.TryDecodeReservationCommand(MutateExpectedAuthoritySession(validCommandBytes),out _));break;case "duplicate-graph-axis":Assert.False(GraphParticipantReservationCodecsV2.TryDecodeReservationCommand(MutateDuplicateGraphAxis(validCommandBytes),out _));break;case "node-order":Assert.False(GraphParticipantReservationCodecsV2.TryDecodeReservationCommandBody(MutateNodeOrder(validCommandBodyBytes),out _));break;case "node-duplicate":Assert.False(GraphParticipantReservationCodecsV2.TryDecodeReservationCommandBody(MutateNodeDuplicate(validCommandBodyBytes),out _));break;case "registration-carrier-bytes":Assert.Throws<ArgumentException>(()=>new LiveAudioParticipantFactoryRegistrationV1(typeof(GraphParticipantCapacityPlanEvidenceV2Tests),"tests:factory",descriptor,MutateCarrierBytes(validCarrierBytes),validCarrierFingerprint));break;case "registration-carrier-fingerprint":Assert.Throws<ArgumentException>(()=>new LiveAudioParticipantFactoryRegistrationV1(typeof(GraphParticipantCapacityPlanEvidenceV2Tests),"tests:factory",descriptor,validCarrierBytes,MutateCarrierFingerprint(validCarrierFingerprint)));break;default:throw new InvalidOperationException();}
        Assert.Equal(expectedRejection,label switch{"expected-authority-session"=>"DecoderRejected","duplicate-graph-axis"=>"DecoderRejected","node-order"=>"DecoderRejected","node-duplicate"=>"DecoderRejected","registration-carrier-bytes"=>"ConstructorRejected","registration-carrier-fingerprint"=>"ConstructorRejected",_=>throw new InvalidOperationException()});
    }

    private static byte[] MutateExpectedAuthoritySession(byte[] validOuter)
    {
        var mutated=validOuter.ToArray();var reader=new CborReader(validOuter,CborConformanceMode.Ctap2Canonical);reader.ReadStartMap();reader.ReadUInt64();var expectedAuthoritySession=SessionAuthorityStampV1Codec.Read(reader);Span<byte> needle=stackalloc byte[16];if(!expectedAuthoritySession.LiveSessionId.TryWriteBytes(needle))throw new InvalidOperationException();var differentSession=(byte)(needle[0]^1);var seen=0;for(var i=0;i<=mutated.Length-needle.Length;i++)if(mutated.AsSpan(i,needle.Length).SequenceEqual(needle)&&++seen==2){mutated[i]=differentSession;return mutated;}throw new InvalidOperationException("Expected duplicated authority session bytes.");
    }
    private static byte[] MutateDuplicateGraphAxis(byte[] validOuter)
    {
        var mutated=validOuter.ToArray();var reader=new CborReader(mutated,CborConformanceMode.Ctap2Canonical);reader.ReadStartMap();reader.ReadUInt64();var session=SessionAuthorityStampV1Codec.Read(reader);reader.ReadUInt64();var authority=AuthorityVectorCodecsV1.ReadVector(reader);reader.ReadUInt64();var body=reader.ReadByteString();var graphAxis=authority.Axes.Single(x=>x.AxisId==AuthorityAxisId.Graph);var duplicateGraphAxis=graphAxis;var writer=new CborWriter(CborConformanceMode.Ctap2Canonical);writer.WriteStartMap(3);writer.WriteUInt64(1);SessionAuthorityStampV1Codec.Write(writer,session);writer.WriteUInt64(2);writer.WriteStartMap(2);writer.WriteUInt64(1);SessionAuthorityStampV1Codec.Write(writer,session);writer.WriteUInt64(2);writer.WriteStartArray(2);AuthorityVectorCodecsV1.Write(writer,graphAxis);AuthorityVectorCodecsV1.Write(writer,duplicateGraphAxis);writer.WriteEndArray();writer.WriteEndMap();writer.WriteUInt64(3);writer.WriteByteString(body);writer.WriteEndMap();mutated=writer.Encode();return mutated;
    }
    private static byte[] MutateNodeOrder(byte[] validBody){var mutated=validBody.ToArray();byte[] orderedNodes=[0x82,0x61,(byte)'a',0x61,(byte)'b'];for(var i=0;i<=mutated.Length-orderedNodes.Length;i++)if(mutated.AsSpan(i,orderedNodes.Length).SequenceEqual(orderedNodes)){var reverseNodes=(byte)'b';mutated[i+2]=reverseNodes;mutated[i+4]=(byte)'a';return mutated;}throw new InvalidOperationException();}
    private static byte[] MutateNodeDuplicate(byte[] validBody){var mutated=validBody.ToArray();byte[] orderedNodes=[0x82,0x61,(byte)'a',0x61,(byte)'b'];for(var i=0;i<=mutated.Length-orderedNodes.Length;i++)if(mutated.AsSpan(i,orderedNodes.Length).SequenceEqual(orderedNodes)){var duplicateNode=(byte)'a';mutated[i+4]=duplicateNode;return mutated;}throw new InvalidOperationException();}
    private static byte[] MutateCarrierBytes(byte[] validCarrier){var mutated=validCarrier.ToArray();var allocationCarrier=mutated.Length;if(allocationCarrier==0)throw new InvalidOperationException();mutated[0]^=1;return mutated;}
    private static Hash256 MutateCarrierFingerprint(Hash256 validFingerprint){Span<byte> fingerprintBytes=stackalloc byte[32];if(!validFingerprint.TryWriteBytes(fingerprintBytes))throw new InvalidOperationException();fingerprintBytes[0]^=1;var result=Hash256.FromBytes(fingerprintBytes);return result;}
